experiment:
# Espressif native USB Serial/JTAG (ESP32-C6, 303a:1001) through the NATIVE Go
# stack: Linux usbfs -> Espressif USB-JTAG transport -> JTAG -> RISC-V Debug
# Module. No OpenOCD, no Python, no ESP-IDF, no libusb, no CGO.
#
# Recorded on a REAL ESP32-C6. Only USB interface 2 (the vendor JTAG
# interface) is claimed; the CDC serial port (/dev/ttyACMx) stays with cdc_acm.
# See docs/notes/phase18-esp-usb-jtag-results.md.
#
#   hwlab devices                         # espusbjtag/303a:1001:<serial>
#   hwlab run --yes examples/espusbjtag-c6.yaml
#
# halt/resume/read_registers need --yes (they change CPU run state). Nothing
# here writes memory or flash, erases, or resets the target. Reads of the
# peripheral window 0x60000000-0x6FFFFFFF are refused by the plugin.
name: espusbjtag-c6
duration: 12s

devices:
  jtag:
    plugin: espusbjtag

steps:
  - {name: info, at: 100ms, device: jtag, call: JTAGTransport.info}
  - {name: scan, at: 500ms, device: jtag, call: JTAGScan.scan, args: {measure_ir: true}}
  - {name: identify, at: 1000ms, device: jtag, call: TargetIdentify.identify}
  - {name: chip-info, at: 1500ms, device: jtag, call: DebugProbe.chip_info}
  - {name: halt, at: 2000ms, device: jtag, call: DebugProbe.halt}
  - {name: registers, at: 2500ms, device: jtag, call: DebugProbe.read_registers, args: {keep_halted: true}}
  - {name: read-rom, at: 3500ms, device: jtag, call: MemoryAccess.read, args: {address: 0x40000000, length: 16}}
  - {name: read-sram, at: 4000ms, device: jtag, call: MemoryAccess.read, args: {address: 0x40800000, length: 16}}
  - {name: read-flash, at: 4500ms, device: jtag, call: MemoryAccess.read, args: {address: 0x42000000, length: 16}}
  - {name: resume, at: 5000ms, device: jtag, call: DebugProbe.resume}
  - {name: scan-again, at: 5500ms, device: jtag, call: JTAGScan.scan, args: {measure_ir: true}}
